    return sum + Math.max(0, Math.abs(boxes[i].x + boxes[i].w / 2 - mx) - (x1 - x0) / k) + Math.max(0, Math.abs(boxes[i].y + boxes[i].h / 2 - my) - (y1 - y0) / k);
