        const Q = { x: P.x.map((v) => mx + (v - mx) * fx), y: P.y.map((v) => my + (v - my) * fy) };
        if (!erSeparate(all, Q, sizes, 60)) continue;
        const bx = toBoxes(Q);
        if (area(bx) > cap || floor(bx) >= cost(cur.key) + T - 1e-6) continue;
        const key = score(bx, cur.key);
