        if (key[0] < c.key[0] && key[1] <= maxX && (!pick || key[0] < pick.key[0] || (key[0] === pick.key[0] && (key[1] < pick.key[1] || (key[1] === pick.key[1] && key[2] < pick.key[2]))))) pick = { key, boxes: bx };
        if (pick && pick.key[0] === 0 && pick.key[1] <= c.key[1]) break;
