  const byDeg = adj.map((a, i) => i).sort((a, b) => adj[b].length - adj[a].length || a - b);
  const hubs = [byDeg[0]].concat(byDeg.slice(1).sort((a, b) => adj[b].length - adj[a].length || (ents[a].id < ents[b].id ? -1 : ents[a].id > ents[b].id ? 1 : 0)).slice(0, 2));
